        ///<summary>
        ///Rekey the abstracted account to another address. Primarily useful for rekeying to an EOA.
        ///</summary>
        /// <param name="address">The address to rekey to </param>
        /// <param name="flash">Whether or not this should be a flash rekey. If true, the rekey back to the app address must done in the same txn group as this call </param>
        public async Task Arc58RekeyTo(Algorand.Address address, bool flash, Account _tx_sender, ulong? _tx_fee, string _tx_note = "", ulong _tx_roundValidity = 1000, List<BoxRef>? _tx_boxes = null, List<Transaction>? _tx_transactions = null, List<ulong>? _tx_assets = null, List<ulong>? _tx_apps = null, List<Address>? _tx_accounts = null, AVM.ClientGenerator.Core.OnCompleteType _tx_callType = AVM.ClientGenerator.Core.OnCompleteType.NoOp)
